/* Renix Clock Card v1.2.1
 * Adaptive geometry based on the original non-adaptive layout.
 * Reference scene: 800 x 480.
 * reNix Regular WOFF2 is embedded in the stylesheet.
 */
const RENIX_BASE_WIDTH = 800;
const RENIX_BASE_HEIGHT = 480;

const RENIX_CSS = `
@font-face{font-family:renix1;src:url("data:font/woff2;base64,") format("woff2");font-weight:400;font-style:normal;font-display:block}
@font-face{
  font-family:renix1;
  src:url("data:font/woff2;base64,REPLACE_WITH_EMBEDDED_RENIX_FONT") format("woff2");
  font-weight:400;
  font-style:normal;
  font-display:block;
}

:host{
  display:block;
  width:100%;
  --renix-orange:#ff7700;
  --renix-frame:rgba(255,119,0,.42);
  --renix-frame-glow:rgba(255,70,0,.22);
}

*{
  box-sizing:border-box;
}

/* =========================================================
   OUTER CARD
   ========================================================= */

.renix-shell{
  position:relative;
  width:100%;
  height:var(--card-height,480px);
  min-height:0;
  overflow:visible;
}

.renix-card{
  position:relative;
  width:100%;
  height:100%;
  overflow:visible;
  background:transparent;
  border:none;
  box-shadow:none;
  border-radius:0;
  backdrop-filter:none;
  -webkit-backdrop-filter:none;
  z-index:1;
}

/*
 * IMPORTANT:
 * The backdrop covers the COMPLETE 800x480 coordinate area.
 * It is NOT part of the clock block.
 */

.renix-shared-backdrop{
  position:absolute;
  left:0;
  top:0;
  width:100%;
  height:100%;
  z-index:0;
  pointer-events:none;

  background:var(--renix-card-background,transparent);
  border:var(--renix-card-border,none);
  box-shadow:var(--renix-card-shadow,none);
  border-radius:var(--renix-card-radius,0);

  backdrop-filter:var(--renix-card-backdrop-filter,none);
  -webkit-backdrop-filter:var(--renix-card-backdrop-filter,none);
}

/* =========================================================
   TOP BLOCK
   Base geometry: 800 x 480
   ========================================================= */

.renix-header{
  position:absolute;
  left:0;
  top:var(--renix-top-top,20px);

  width:100%;
  height:var(--renix-top-height,55px);

  display:flex;
  align-items:center;
  justify-content:center;

  z-index:30;
  pointer-events:none;
}

.renix-date{
  position:relative;

  display:flex;
  align-items:center;
  justify-content:center;

  width:max-content;
  max-width:100%;

  gap:var(--renix-top-gap,14px);

  font-family:Roboto,Arial,sans-serif;
  font-size:var(--renix-top-font-size,36.8px);
  font-weight:300;
  line-height:1.2;
  letter-spacing:1px;

  color:var(--renix-clock-color,#ff7700);

  text-shadow:
    0 0 var(--renix-glow-4,4px) var(--renix-clock-glow-color,#ff3300),
    0 0 var(--renix-glow-10,10px) var(--renix-clock-glow-color,#ff5500),
    0 0 var(--renix-glow-20,20px) var(--renix-clock-color,#ff7700);

  white-space:nowrap;
  z-index:30;
}

.renix-top-weather{
  display:flex;
  align-items:center;
  justify-content:center;
}

.renix-weather-icon{
  display:flex;
  align-items:center;
  justify-content:center;

  width:var(--renix-top-icon-size,42px);
  height:var(--renix-top-icon-size,42px);

  flex-shrink:0;
}

.renix-weather-icon ha-icon{
  --mdc-icon-size:var(--renix-top-icon-size,42px);

  width:var(--renix-top-icon-size,42px);
  height:var(--renix-top-icon-size,42px);

  color:var(--renix-clock-color,#ff7700);

  filter:
    drop-shadow(
      0 0 var(--renix-glow-4,4px)
      var(--renix-clock-glow-color,#ff3300)
    )
    drop-shadow(
      0 0 var(--renix-glow-10,10px)
      var(--renix-clock-glow-color,#ff5500)
    );
}

.renix-top-text{
  display:flex;
  align-items:center;
  justify-content:center;
  white-space:nowrap;
}

/* =========================================================
   CLOCK
   Base position: x=0..800 / y≈75..305
   ========================================================= */

.renix-clock{
  position:absolute;

  left:50%;
  top:var(--renix-clock-top,75px);

  transform:translateX(-50%);

  width:100%;
  height:var(--renix-clock-height,230px);

  overflow:visible;

  z-index:10;
}

.renix-digit-layer{
  position:absolute;

  top:0;
  height:100%;

  display:flex;
  align-items:flex-end;

  font-family:renix1,monospace;
  font-size:calc(17rem * var(--renix-scale,1));
  font-weight:400;
  font-style:normal;

  line-height:.95;
  letter-spacing:-.12em;

  white-space:nowrap;
  pointer-events:none;
}

.renix-digit-layer span,
.renix-grid span,
.renix-seconds-layer span{
  display:block;
  white-space:nowrap;
}

.renix-hours-layer{
  right:calc(50% + .2em);
}

.renix-minutes-layer{
  left:calc(50% + .07em);
}

/* =========================================================
   NIXIE LAYERS
   ========================================================= */

.renix-ss03{
  font-feature-settings:"ss03" 1;

  color:rgba(255,119,0,.13);

  text-shadow:
    0 0 2px rgba(255,80,0,.07),
    0 0 4px rgba(255,80,0,.035);

  opacity:.72;
  z-index:1;
}

.renix-base{
  font-feature-settings:normal;

  color:var(--renix-clock-color,#ff7700);

  text-shadow:
    0 0 var(--renix-glow-4,4px)
      var(--renix-clock-glow-color,#ff3300),

    0 0 var(--renix-glow-10,10px)
      var(--renix-clock-glow-color,#ff5500),

    0 0 var(--renix-glow-20,20px)
      var(--renix-clock-color,#ff7700),

    0 0 var(--renix-glow-30,30px)
      rgba(255,85,0,.4);

  opacity:1;
  z-index:2;
}

.renix-ss02{
  font-feature-settings:"ss02" 1;

  color:rgba(75,32,7,.62);

  text-shadow:
    0 0 1px rgba(80,30,5,.25),
    0 0 2px rgba(70,25,4,.1);

  opacity:.68;
  z-index:4;
}

/* =========================================================
   GRID
   ========================================================= */

.renix-grid{
  position:absolute;

  top:0;
  height:100%;

  display:flex;
  align-items:flex-end;

  font-family:renix1,monospace;
  font-size:calc(17rem * var(--renix-scale,1));
  font-weight:400;
  font-style:normal;

  line-height:.95;
  letter-spacing:-.12em;

  white-space:nowrap;
  pointer-events:none;

  z-index:3;

  color:transparent;

  background:
    repeating-linear-gradient(
      0deg,
      rgba(0,0,0,0) 0,
      rgba(0,0,0,0) calc(5px * var(--renix-scale,1)),
      rgba(0,0,0,.9) calc(5px * var(--renix-scale,1)),
      rgba(0,0,0,.4) calc(6px * var(--renix-scale,1))
    ),
    repeating-linear-gradient(
      90deg,
      rgba(0,0,0,0) 0,
      rgba(0,0,0,0) calc(5px * var(--renix-scale,1)),
      rgba(0,0,0,.9) calc(5px * var(--renix-scale,1)),
      rgba(0,0,0,.4) calc(6px * var(--renix-scale,1))
    );

  -webkit-background-clip:text;
  background-clip:text;
  -webkit-text-fill-color:transparent;

  text-shadow:0 0 2px rgba(255,110,0,.25);
}

.renix-grid span{
  background:
    repeating-linear-gradient(
      0deg,
      rgba(255,190,90,0) 0,
      rgba(255,190,90,0) calc(5px * var(--renix-scale,1)),
      rgba(255,190,90,.48) calc(5px * var(--renix-scale,1)),
      rgba(255,190,90,.48) calc(6px * var(--renix-scale,1))
    ),
    repeating-linear-gradient(
      90deg,
      rgba(255,190,90,0) 0,
      rgba(255,190,90,0) calc(5px * var(--renix-scale,1)),
      rgba(255,190,90,.42) calc(5px * var(--renix-scale,1)),
      rgba(255,190,90,.42) calc(6px * var(--renix-scale,1))
    );

  -webkit-background-clip:text;
  background-clip:text;
  -webkit-text-fill-color:transparent;
}

/* =========================================================
   COLON
   ========================================================= */

.renix-colon{
  position:absolute;

  left:50%;
  top:50%;

  transform:translate(-50%,-50%);

  width:calc(18px * var(--renix-scale,1));
  height:calc(150px * var(--renix-scale,1));

  z-index:10;
  pointer-events:none;
}

.renix-colon span{
  position:absolute;

  left:50%;

  width:calc(13px * var(--renix-scale,1));
  height:calc(13px * var(--renix-scale,1));

  margin-left:calc(-6.5px * var(--renix-scale,1));

  border-radius:50%;

  background:var(--renix-clock-color,#ff7700);

  box-shadow:
    0 0 var(--renix-glow-4,4px)
      var(--renix-clock-glow-color,#ff3300),

    0 0 var(--renix-glow-10,10px)
      var(--renix-clock-glow-color,#ff5500),

    0 0 var(--renix-glow-20,20px)
      var(--renix-clock-color,#ff7700);
}

.renix-colon span:first-child{
  top:calc(25px * var(--renix-scale,1));
}

.renix-colon span:last-child{
  bottom:calc(25px * var(--renix-scale,1));
}

/* =========================================================
   SECONDS
   ========================================================= */

.renix-seconds-layer{
  position:absolute;

  left:calc(50% + 4.5em);
  bottom:calc(4px * var(--renix-scale,1));

  width:max-content;
  height:auto;

  display:block;

  font-family:renix1,monospace;
  font-size:calc(6rem * var(--renix-scale,1));
  font-weight:400;
  font-style:normal;

  line-height:.95;
  letter-spacing:-.12em;

  white-space:nowrap;
  pointer-events:none;
}

.renix-seconds-ss03{
  font-feature-settings:"ss03" 1;

  color:rgba(255,119,0,.13);

  text-shadow:
    0 0 1px rgba(255,80,0,.07),
    0 0 3px rgba(255,80,0,.035);

  opacity:.72;
  z-index:17;
}

.renix-seconds-base{
  font-feature-settings:normal;

  color:var(--renix-clock-color,#ff7700);

  text-shadow:
    0 0 calc(3px * var(--renix-clock-glow,1))
      var(--renix-clock-glow-color,#ff3300),

    0 0 calc(7px * var(--renix-clock-glow,1))
      var(--renix-clock-glow-color,#ff5500),

    0 0 calc(14px * var(--renix-clock-glow,1))
      var(--renix-clock-color,#ff7700),

    0 0 calc(22px * var(--renix-clock-glow,1))
      rgba(255,85,0,.4);

  opacity:1;
  z-index:18;
}

.renix-seconds-ss02{
  font-feature-settings:"ss02" 1;

  color:rgba(75,32,7,.62);

  text-shadow:
    0 0 1px rgba(80,30,5,.25),
    0 0 2px rgba(70,25,4,.1);

  opacity:.68;
  z-index:19;
}

/* =========================================================
   BOTTOM SENSOR AREA
   Base: y=330..470
   ========================================================= */

.renix-bottom-area{
  position:absolute;

  left:0;
  top:var(--renix-bottom-top,330px);

  width:100%;
  height:var(--renix-bottom-height,140px);

  overflow:visible;

  z-index:20;
}

.bottom-grid{
  position:absolute;

  left:0;
  top:0;

  width:100%;
  height:100%;

  display:grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap:0;

  margin:0;

  align-items:stretch;
}

/* =========================================================
   SENSOR CARDS
   ========================================================= */

.info-card{
  min-width:0;

  overflow:hidden;

  background:transparent;
  border:none;
  box-shadow:none;

  font-family:"Nixie One",monospace;
}

.info-title{
  display:flex;
  justify-content:center;
  align-items:center;

  width:100%;

  text-align:center;

  padding:0;

  font-family:"Nixie One",monospace;

  font-size:calc(1.8rem * var(--renix-scale,1));
  font-weight:900;

  line-height:1.2;

  color:
    var(--renix-title-color,
    rgba(255,119,0,.8));

  text-transform:uppercase;

  letter-spacing:
    calc(2px * var(--renix-scale,1));

  text-shadow:
    0 0 calc(4px * var(--renix-scale,1))
    rgba(255,51,0,.5);
}

.info-content{
  width:100%;

  padding:
    0
    calc(16px * var(--renix-scale,1))
    calc(12px * var(--renix-scale,1));

  height:
    calc(
      100% -
      34px * var(--renix-scale,1)
    );

  min-height:0;

  display:flex;

  flex-direction:column;

  justify-content:center;
  align-items:center;

  gap:0;
}

.info-value{
  width:100%;

  text-align:center;

  font-family:"Nixie One",monospace;

  font-size:
    calc(5rem * var(--renix-scale,1));

  font-weight:900;

  line-height:1.05;

  white-space:nowrap;

  color:var(--value-color);

  -webkit-text-stroke:
    calc(1.5px * var(--renix-scale,1))
    var(--stroke-color);

  text-shadow:
    0 0 calc(10px * var(--renix-scale,1))
      var(--stroke-color),

    0 0 calc(20px * var(--renix-scale,1))
      var(--glow-color);
}

.info-secondary{
  width:100%;

  text-align:center;

  font-family:"Nixie One",monospace;

  font-size:
    calc(5rem * var(--renix-scale,1));

  font-weight:900;

  line-height:1.05;

  white-space:nowrap;

  color:var(--secondary-color);

  -webkit-text-stroke:
    calc(1.5px * var(--renix-scale,1))
    var(--secondary-stroke);

  text-shadow:
    0 0 calc(10px * var(--renix-scale,1))
      var(--secondary-stroke),

    0 0 calc(20px * var(--renix-scale,1))
      var(--secondary-glow);
}

/* =========================================================
   NIGHT MODE
   ========================================================= */

.renix-card.night .renix-top-item{
  filter:
    brightness(var(--renix-top-brightness,.5));
}

.renix-card.night .renix-colon,
.renix-card.night .renix-date,
.renix-card.night .renix-weather-icon{
  filter:
    brightness(var(--renix-top-brightness,.5));
}

.bottom-grid.night .info-title,
.bottom-grid.night .info-value,
.bottom-grid.night .info-secondary{
  filter:
    brightness(var(--renix-bottom-brightness,.5));

  transition:
    filter .8s ease-in-out;
}

/* =========================================================
   VISIBILITY
   ========================================================= */

.renix-card.hide-grid .renix-grid{
  display:none;
}

.renix-card.hide-inactive .renix-ss02,
.renix-card.hide-inactive .renix-ss03,
.renix-card.hide-inactive .renix-seconds-ss02,
.renix-card.hide-inactive .renix-seconds-ss03{
  display:none;
}

.empty{
  visibility:hidden;
}

@supports (-webkit-hyphens:none){
  .info-value{
    text-shadow:
      0 0 calc(5px * var(--renix-scale,1))
      var(--stroke-color),

      0 0 calc(10px * var(--renix-scale,1))
      var(--glow-color);
  }

  .info-secondary{
    text-shadow:
      0 0 calc(5px * var(--renix-scale,1))
      var(--secondary-stroke),

      0 0 calc(10px * var(--renix-scale,1))
      var(--secondary-glow);
  }
}
`;


class RenixClockCard extends HTMLElement {

  constructor(){
    super();

    this.attachShadow({mode:'open'});

    this._config={};
    this._timer=null;
    this._hass=null;

    this._resizeObserver=null;
    this._resizeQueued=false;
  }


  setConfig(config){

    if(!config){
      throw new Error(
        'renix-clock-card: configuration is required'
      );
    }

    const legacyNight =
      config.night_brightness != null
        ? Number(config.night_brightness)
        : 0.5;

    this._config={

      language:
        config.language || 'auto',

      weather_entity:
        config.weather_entity || '',

      night_entity:
        config.night_entity || '',

      outside_temperature:
        config.outside_temperature || '',

      outside_humidity:
        config.outside_humidity || '',

      pressure_entity:
        config.pressure_entity || '',

      room_temperature:
        config.room_temperature || '',

      room_humidity:
        config.room_humidity || '',


      /* bottom */

      show_bottom_cards:
        config.show_bottom_cards !== false,


      /* geometry */

      height:
        Number(config.height) || 480,

      adaptive:
        config.adaptive !== false,


      /* top block */

      show_top_block:
        config.show_top_block !== false,

      show_top_weather:
        config.show_top_weather !== false,

      show_top_date:
        config.show_top_date !== false,

      show_top_weekday:
        config.show_top_weekday !== false,

      top_font_size:
        Number(config.top_font_size) || 2.3,

      top_icon_size:
        Number(config.top_icon_size) || 42,

      top_gap:
        Number(config.top_gap) || 14,

      top_offset:
        Number(config.top_offset) || 20,


      /* card */

      card_background:
        config.card_background ?? null,

      card_border:
        config.card_border ?? null,

      card_shadow:
        config.card_shadow ?? null,

      card_radius:
        config.card_radius ?? null,

      card_backdrop_blur:
        config.card_backdrop_blur != null
          ? Number(config.card_backdrop_blur)
          : (
              config.card_backdrop_filter
                ? Number(
                    (
                      String(
                        config.card_backdrop_filter
                      ).match(
                        /blur\\(([-0-9.]+)px\\)/
                      ) || []
                    )[1] || 10
                  )
                : 10
            ),

      card_background_color:
        config.card_background_color ?? null,

      card_background_opacity:
        config.card_background_opacity != null
          ? Number(config.card_background_opacity)
          : 0.08,

      card_border_color:
        config.card_border_color ?? null,

      card_border_opacity:
        config.card_border_opacity != null
          ? Number(config.card_border_opacity)
          : 0.15,

      card_shadow_color:
        config.card_shadow_color ?? null,

      card_shadow_opacity:
        config.card_shadow_opacity != null
          ? Number(config.card_shadow_opacity)
          : 0.25,


      /* night */

      top_night_brightness:
        config.top_night_brightness != null
          ? Number(config.top_night_brightness)
          : legacyNight,

      bottom_night_brightness:
        config.bottom_night_brightness != null
          ? Number(config.bottom_night_brightness)
          : legacyNight,


      /* clock */

      clock_color:
        config.clock_color || '#ff7700',

      clock_glow_color:
        config.clock_glow_color || '#ff5500',

      clock_glow:
        config.clock_glow != null
          ? Number(config.clock_glow)
          : 1,


      /* sensors */

      outside_color:
        config.outside_color || '#009030',

      outside_stroke:
        config.outside_stroke || '#209030',

      outside_glow:
        config.outside_glow ||
        'rgba(0,153,16,.5)',


      pressure_color:
        config.pressure_color || '#0099bb',

      pressure_stroke:
        config.pressure_stroke || '#3377dd',

      pressure_glow:
        config.pressure_glow ||
        'rgba(0,153,187,.5)',


      room_color:
        config.room_color || '#bbbb00',

      room_stroke:
        config.room_stroke || '#bbbb55',

      room_glow:
        config.room_glow ||
        'rgba(187,187,0,.5)',


      title_color:
        config.title_color ||
        'rgba(255,119,0,.8)',


      show_grid:
        config.show_grid !== false,

      show_inactive_threads:
        config.show_inactive_threads !== false
    };

    this._render();
  }


  set hass(hass){
    this._hass=hass;
    this._render();
  }


  connectedCallback(){

    this._start();
    this._observeSize();
  }


  disconnectedCallback(){

    clearTimeout(this._timer);
    this._timer=null;

    if(this._resizeObserver){
      this._resizeObserver.disconnect();
      this._resizeObserver=null;
    }
  }


  _start(){

    if(this._timer){
      return;
    }

    this._scheduleNextSecond();
  }


  _scheduleNextSecond(){

    clearTimeout(this._timer);

    const delay=
      1000 -
      (Date.now()%1000);

    this._timer=setTimeout(()=>{

      this._timer=null;

      this._render();

      this._scheduleNextSecond();

    },delay);
  }


  /* =======================================================
     ADAPTIVE SIZE
     ======================================================= */

  _observeSize(){

    if(
      this._resizeObserver ||
      typeof ResizeObserver === 'undefined'
    ){
      return;
    }

    this._resizeObserver=
      new ResizeObserver(()=>{

        if(this._resizeQueued){
          return;
        }

        this._resizeQueued=true;

        requestAnimationFrame(()=>{

          this._resizeQueued=false;

          this._applyAdaptiveSize();

        });

      });

    this._resizeObserver.observe(this);

    this._applyAdaptiveSize();
  }


  _applyAdaptiveSize(){

    if(!this._config?.adaptive){
      return;
    }

    if(!this.shadowRoot){
      return;
    }

    /*
     * The IMPORTANT change:
     *
     * Do NOT use current element height as the
     * scale source.
     *
     * Width is the real available Lovelace card width.
     *
     * Base geometry = 800 x 480.
     */

    const rect=
      this.getBoundingClientRect();

    const width=
      rect.width || RENIX_BASE_WIDTH;

    const scale=
      Math.max(
        0.45,
        Math.min(
          2.5,
          width / RENIX_BASE_WIDTH
        )
      );

    const height=
      RENIX_BASE_HEIGHT * scale;


    this.style.setProperty(
      '--renix-scale',
      String(scale)
    );

    this.style.setProperty(
      '--card-height',
      `${height}px`
    );


    /* Top block */

    this.style.setProperty(
      '--renix-top-top',
      `${this._config.top_offset * scale}px`
    );

    this.style.setProperty(
      '--renix-top-height',
      `${55 * scale}px`
    );

    this.style.setProperty(
      '--renix-top-font-size',
      `${this._config.top_font_size * 16 * scale}px`
    );

    this.style.setProperty(
      '--renix-top-icon-size',
      `${this._config.top_icon_size * scale}px`
    );

    this.style.setProperty(
      '--renix-top-gap',
      `${this._config.top_gap * scale}px`
    );


    /* Clock */

    this.style.setProperty(
      '--renix-clock-top',
      `${75 * scale}px`
    );

    this.style.setProperty(
      '--renix-clock-height',
      `${230 * scale}px`
    );


    /*
     * Bottom area deliberately starts at 330
     * in the 800x480 reference geometry.
     *
     * Clock ends at 305.
     * Therefore there is a 25px reference gap.
     */

    this.style.setProperty(
      '--renix-bottom-top',
      `${330 * scale}px`
    );

    this.style.setProperty(
      '--renix-bottom-height',
      `${140 * scale}px`
    );
  }


  _applyManualSize(){

    const height=
      Number(this._config.height) || RENIX_BASE_HEIGHT;

    this.style.setProperty(
      '--renix-scale',
      '1'
    );

    this.style.setProperty(
      '--card-height',
      `${height}px`
    );


    this.style.setProperty(
      '--renix-top-top',
      `${this._config.top_offset}px`
    );

    this.style.setProperty(
      '--renix-top-height',
      '55px'
    );

    this.style.setProperty(
      '--renix-top-font-size',
      `${this._config.top_font_size * 16}px`
    );

    this.style.setProperty(
      '--renix-top-icon-size',
      `${this._config.top_icon_size}px`
    );

    this.style.setProperty(
      '--renix-top-gap',
      `${this._config.top_gap}px`
    );

    this.style.setProperty(
      '--renix-clock-top',
      '75px'
    );

    this.style.setProperty(
      '--renix-clock-height',
      '230px'
    );

    this.style.setProperty(
      '--renix-bottom-top',
      '330px'
    );

    this.style.setProperty(
      '--renix-bottom-height',
      `${Math.max(140,height-340)}px`
    );
  }


  _state(id){
    return id &&
      this._hass?.states?.[id] ||
      null;
  }


  _val(id){
    return this._state(id)?.state ?? '—';
  }


  _unit(id){
    return this._state(id)?.attributes?.unit_of_measurement || '';
  }


  _weatherIcon(state){

    return ({
      'clear-night':'mdi:weather-night',
      cloudy:'mdi:weather-cloudy',
      fog:'mdi:weather-fog',
      hail:'mdi:weather-hail',
      lightning:'mdi:weather-lightning',

      'lightning-rainy':
        'mdi:weather-lightning-rainy',

      partlycloudy:
        'mdi:weather-partly-cloudy',

      pouring:'mdi:weather-pouring',
      rainy:'mdi:weather-rainy',
      snowy:'mdi:weather-snowy',

      'snowy-rainy':
        'mdi:weather-snowy-rainy',

      sunny:'mdi:weather-sunny',
      windy:'mdi:weather-windy',

      'windy-variant':
        'mdi:weather-windy-variant',

      exceptional:
        'mdi:weather-cloudy-alert'

    })[state] || 'mdi:weather-cloudy';
  }


  _escape(v){

    return String(v).replace(
      /[&<>"']/g,
      c=>({
        '&':'&amp;',
        '<':'&lt;',
        '>':'&gt;',
        '"':'&quot;',
        "'":'&#39;'
      })[c]
    );
  }


  _css(v){

    return v==null || v===''
      ? 'transparent'
      : String(v);
  }


  _rgba(color,opacity){

    if(!color){
      return 'transparent';
    }

    const m=
      String(color).match(
        /^#([0-9a-f]{6})$/i
      );

    if(!m){
      return color;
    }

    const n=
      parseInt(m[1],16);

    return `rgba(
      ${n>>16},
      ${(n>>8)&255},
      ${n&255},
      ${Math.max(
        0,
        Math.min(1,Number(opacity))
      )}
    )`;
  }


  _render(){

    if(
      !this.shadowRoot ||
      !this._config
    ){
      return;
    }

    const now=new Date();

    const h=
      String(now.getHours())
      .padStart(2,'0');

    const m=
      String(now.getMinutes())
      .padStart(2,'0');

    const s=
      String(now.getSeconds())
      .padStart(2,'0');


    const language=
      this._config.language==='auto'
        ? (
            String(
              this._hass?.locale?.language ||
              this._hass?.language ||
              navigator.language ||
              'en'
            )
            .toLowerCase()
            .startsWith('ru')
              ? 'ru'
              : 'en'
          )
        : this._config.language;


    const L=
      language==='ru'
        ? {
            months:[
              'января','февраля','марта',
              'апреля','мая','июня',
              'июля','августа','сентября',
              'октября','ноября','декабря'
            ],

            days:[
              'Понедельник',
              'Вторник',
              'Среда',
              'Четверг',
              'Пятница',
              'Суббота',
              'Воскресенье'
            ],

            year:'года',
            outside:'Улица',
            pressure:'Давление',
            room:'Спальня'
          }

        : {
            months:[
              'January','February','March',
              'April','May','June',
              'July','August','September',
              'October','November','December'
            ],

            days:[
              'Monday','Tuesday','Wednesday',
              'Thursday','Friday','Saturday',
              'Sunday'
            ],

            year:'',
            outside:'Outside',
            pressure:'Pressure',
            room:'Bedroom'
          };


    const fullDate=
      language==='ru'
        ? `${now.getDate()} ${
            L.months[now.getMonth()]
          } ${
            now.getFullYear()
          } ${L.year}`

        : `${L.months[now.getMonth()]} ${
            now.getDate()
          }, ${
            now.getFullYear()
          }`;


    const weekday=
      L.days[
        (now.getDay()+6)%7
      ];


    const night=
      this._state(
        this._config.night_entity
      )?.state==='on';


    const weather=
      this._state(
        this._config.weather_entity
      );

    const wi=
      this._weatherIcon(
        weather?.state || ''
      );


    const C=this._config;


    const temp=
      this._escape(
        this._val(C.outside_temperature)
      );

    const hum=
      this._escape(
        this._val(C.outside_humidity)
      );


    const pressRaw=
      this._val(C.pressure_entity);

    const press=
      this._escape(
        Number.isFinite(
          Number(pressRaw)
        )
          ? Number(pressRaw).toFixed(1)
          : pressRaw
      );


    const rt=
      this._escape(
        this._val(C.room_temperature)
      );

    const rh=
      this._escape(
        this._val(C.room_humidity)
      );


    const tu=
      this._escape(
        this._unit(C.outside_temperature)
      );

    const hu=
      this._escape(
        this._unit(C.outside_humidity)
      );

    const pu=
      this._escape(
        this._unit(C.pressure_entity)
      );

    const ru=
      this._escape(
        this._unit(C.room_temperature)
      );

    const rhu=
      this._escape(
        this._unit(C.room_humidity)
      );


    /* =====================================================
       TOP BLOCK
       ===================================================== */

    let topParts='';


    if(C.show_top_weather){

      topParts+=`
        <span class="renix-top-weather">
          <span class="renix-weather-icon">
            <ha-icon icon="${wi}"></ha-icon>
          </span>
        </span>
      `;
    }


    if(C.show_top_date){

      topParts+=`
        <span class="renix-top-text">
          ${this._escape(fullDate)}
        </span>
      `;
    }


    if(C.show_top_weekday){

      topParts+=`
        <span class="renix-top-text">
          ${this._escape(weekday)}
        </span>
      `;
    }


    const top=
      C.show_top_block && topParts
        ? `
          <div class="renix-header">
            <div class="renix-date">
              ${topParts}
            </div>
          </div>
        `
        : '';


    /* =====================================================
       SENSOR CARDS
       ===================================================== */

    const info=(
      title,
      value,
      unit,
      secondary,
      secondaryUnit,
      color,
      stroke,
      glow
    )=>`

      <div class="info-card">

        <div class="info-title">
          ${title}
        </div>

        <div class="info-content">

          <div
            class="info-value"
            style="
              --value-color:${color};
              --stroke-color:${stroke};
              --glow-color:${glow}
            "
          >
            ${value}

            ${
              unit
                ? `
                  <span
                    style="
                      font-size:.55em;
                      margin-left:.08em
                    "
                  >
                    ${unit}
                  </span>
                `
                : ''
            }
          </div>

          ${
            secondary !== ''
              ? `
                <div
                  class="info-secondary"
                  style="
                    --secondary-color:${color};
                    --secondary-stroke:${stroke};
                    --secondary-glow:${glow}
                  "
                >
                  ${secondary}

                  ${
                    secondaryUnit
                      ? `
                        <span
                          style="
                            font-size:.55em;
                            margin-left:.08em
                          "
                        >
                          ${secondaryUnit}
                        </span>
                      `
                      : ''
                  }
                </div>
              `
              : ''
          }

        </div>

      </div>
    `;


    const bottom=
      C.show_bottom_cards

        ? `
          <div
            class="
              bottom-grid
              ${night?'night':''}
            "
            style="
              --renix-title-color:${C.title_color};
              --renix-bottom-brightness:
                ${C.bottom_night_brightness}
            "
          >

            ${info(
              L.outside,
              temp,
              tu,
              hum,
              hu,
              C.outside_color,
              C.outside_stroke,
              C.outside_glow
            )}

            ${info(
              L.pressure,
              press,
              pu,
              '',
              '',
              C.pressure_color,
              C.pressure_stroke,
              C.pressure_glow
            )}

            ${info(
              L.room,
              rt,
              ru,
              rh,
              rhu,
              C.room_color,
              C.room_stroke,
              C.room_glow
            )}

          </div>
        `
        : '';


    if(C.adaptive){
      this._applyAdaptiveSize();
    }else{
      this._applyManualSize();
    }


    this.shadowRoot.innerHTML=`

      <style>
        ${RENIX_CSS}
      </style>

      <div
        class="renix-shell"

        style="
          --renix-card-background:
            ${
              C.card_background_color
                ? this._rgba(
                    C.card_background_color,
                    C.card_background_opacity
                  )
                : this._css(
                    C.card_background
                  )
            };

          --renix-card-border:
            ${
              C.card_border_color
                ? `
                  1px solid ${
                    this._rgba(
                      C.card_border_color,
                      C.card_border_opacity
                    )
                  }
                `
                : this._css(
                    C.card_border
                  )
            };

          --renix-card-shadow:
            ${
              C.card_shadow_color
                ? `
                  0 8px 32px ${
                    this._rgba(
                      C.card_shadow_color,
                      C.card_shadow_opacity
                    )
                  }
                `
                : this._css(
                    C.card_shadow
                  )
            };

          --renix-card-radius:
            ${this._css(C.card_radius)};

          /*
           * Blur belongs to the COMPLETE card.
           */
          --renix-card-backdrop-filter:
            blur(${Math.max(
              0,
              C.card_backdrop_blur
            )}px);

          --renix-clock-color:
            ${C.clock_color};

          --renix-clock-glow-color:
            ${C.clock_glow_color};

          --renix-glow-4:
            ${4*C.clock_glow}px;

          --renix-glow-10:
            ${10*C.clock_glow}px;

          --renix-glow-20:
            ${20*C.clock_glow}px;

          --renix-glow-30:
            ${30*C.clock_glow}px;

          --renix-clock-glow:
            ${C.clock_glow};

          --renix-title-color:
            ${C.title_color};

          --renix-top-brightness:
            ${C.top_night_brightness};
        "
      >

        <div class="renix-shared-backdrop"></div>

        <div
          class="
            renix-card
            ${night?'night ':''}
            ${C.show_grid?'':'hide-grid '}
            ${C.show_inactive_threads?'':'hide-inactive'}
          "
        >

          ${top}


          <div class="renix-clock">

            <div class="renix-top">

              <div
                class="
                  renix-digit-layer
                  renix-top-item
                  renix-hours-layer
                  renix-ss03
                "
              >
                <span>${h}</span>
              </div>

              <div
                class="
                  renix-digit-layer
                  renix-top-item
                  renix-hours-layer
                  renix-base
                "
              >
                <span>${h}</span>
              </div>

              <div
                class="
                  renix-grid
                  renix-top-item
                  renix-hours-layer
                "
              >
                <span>${h}</span>
              </div>

              <div
                class="
                  renix-digit-layer
                  renix-top-item
                  renix-hours-layer
                  renix-ss02
                "
              >
                <span>${h}</span>
              </div>


              <div
                class="
                  renix-digit-layer
                  renix-top-item
                  renix-minutes-layer
                  renix-ss03
                "
              >
                <span>${m}</span>
              </div>

              <div
                class="
                  renix-digit-layer
                  renix-top-item
                  renix-minutes-layer
                  renix-base
                "
              >
                <span>${m}</span>
              </div>

              <div
                class="
                  renix-grid
                  renix-top-item
                  renix-minutes-layer
                "
              >
                <span>${m}</span>
              </div>

              <div
                class="
                  renix-digit-layer
                  renix-top-item
                  renix-minutes-layer
                  renix-ss02
                "
              >
                <span>${m}</span>
              </div>


              <div class="renix-colon">
                <span></span>
                <span></span>
              </div>


              <div
                class="
                  renix-seconds-layer
                  renix-top-item
                  renix-seconds-ss03
                "
              >
                <span>${s}</span>
              </div>

              <div
                class="
                  renix-seconds-layer
                  renix-top-item
                  renix-seconds-base
                "
              >
                <span>${s}</span>
              </div>

              <div
                class="
                  renix-seconds-layer
                  renix-top-item
                  renix-seconds-ss02
                "
              >
                <span>${s}</span>
              </div>

            </div>

          </div>


          ${
            C.show_bottom_cards
              ? `
                <div class="renix-bottom-area">
                  ${bottom}
                </div>
              `
              : ''
          }

        </div>

      </div>
    `;

    /*
     * Render replaces shadowRoot contents.
     * Re-apply adaptive geometry after DOM creation.
     */
    if(C.adaptive){
      requestAnimationFrame(
        ()=>this._applyAdaptiveSize()
      );
    }
  }


  getCardSize(){

    return this._config.show_bottom_cards
      ? 5
      : 4;
  }


  static getConfigElement(){

    return document.createElement(
      'renix-clock-card-editor'
    );
  }


  static getStubConfig(){

    return {
      weather_entity:
        'weather.yandex_pogoda',

      night_entity:
        'input_boolean.night_mode',

      outside_temperature:
        'sensor.spalnia_ulitsa_temperature',

      outside_humidity:
        'sensor.spalnia_ulitsa_humidity',

      pressure_entity:
        'sensor.spalnia_atmospheric_pressure',

      room_temperature:
        'sensor.spalnia_temperature',

      room_humidity:
        'sensor.spalnia_humidity'
    };
  }
}


